head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDBNF05002";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_datefmt_cal_coupnRtDecsnBasDd();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf05002.onpageload' });
    }
};

/**
 * @method
 * @name init_datefmt_cal_coupnRtDecsnBasDd
 * @description 초기화 — datefmt cal coupn Rt Decsn Bas Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_coupnRtDecsnBasDd = function () { $c.date.checkCalendarFormat("cal_coupnRtDecsnBasDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.makeInputFromParent();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05002.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldbnf05002: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_coupnRtDecsnBasIntCd_onchange
 * @description slc_coupnRtDecsnBasIntCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_coupnRtDecsnBasIntCd_onchange = async function(e){
    try {
        await scwin.Etc_select();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05002.slc_coupnRtDecsnBasIntCd_onchange' }); }
};

/**
 * @method
 * @name ipt_coupnRtMiscBasIntContn_onpaste
 * @description ipt_coupnRtMiscBasIntContn onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_coupnRtMiscBasIntContn_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05002.ipt_coupnRtMiscBasIntContn_onpaste' }); }
};

/**
 * @method
 * @name ipt_coupnRtDecsnSpd_onpaste
 * @description ipt_coupnRtDecsnSpd onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_coupnRtDecsnSpd_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05002.ipt_coupnRtDecsnSpd_onpaste' }); }
};

/**
 * @method
 * @name btn_cStdIntForm_onclick
 * @description btn_cStdIntForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_cStdIntForm_onclick = async function(e){
    try {
        await scwin.c_std_int_form('ok')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05002.btn_cStdIntForm_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05002.btn_self_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name makeInputFromParent
 * @description make Input From Parent 처리
 * @returns {void}
 * @hidden N
 */
scwin.makeInputFromParent = function () {

    const parentfm = ((scwin.openerScwin())["SendForm"] !== undefined ? (scwin.openerScwin())["SendForm"] : undefined);
    $c.util.getComponent("slc_coupnRtDecsnBasIntCd").setValue(parentfm.coupn_rt_decsn_bas_int_cd.value);
    let v_str = parentfm.coupn_rt_decsn_bas_int_cd.value;
    if (v_str === '90') {
        $c.util.getComponent('ipt_coupnRtMiscBasIntContn').setDisabled(false);
    }
    $c.util.getComponent("slc_coupnRtRemainPdCd").setValue(parentfm.coupn_rt_remain_pd_cd.value);
    $c.util.getComponent("slc_coupnRtDecsnSpdSgn").setValue(parentfm.coupn_rt_decsn_spd_sgn.value);
    $c.util.getComponent("ipt_coupnRtDecsnSpd").setValue(parentfm.coupn_rt_decsn_spd.value);
    $c.util.getComponent("cal_coupnRtDecsnBasDd").setValue(parentfm.coupn_rt_decsn_bas_dd.value);
    $c.util.getComponent("ipt_coupnRtDecsnTm").setValue(parentfm.coupn_rt_decsn_tm.value);
    v_str = parentfm.coupn_rt_decsn_tm.value;
    if (v_str === '1') {
        /* 수동 전환 필요: coupn_rt_decsn_tm[0] 선택 — 옵션표 미해결 */ void 0;
    } else {
        if (v_str === '2') {
            /* 수동 전환 필요: coupn_rt_decsn_tm[1] 선택 — 옵션표 미해결 */ void 0;
        }
    }
    $c.util.getComponent("ipt_coupnRtMiscBasIntContn").setValue(parentfm.coupn_rt_misc_bas_int_contn.value);
};

/**
 * @method
 * @name Etc_select
 * @description Etc select 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.Etc_select = async function () {
    if ($c.util.getComponent('slc_coupnRtDecsnBasIntCd').getValue() === '90') {
        $c.util.getComponent('ipt_coupnRtMiscBasIntContn').setDisabled(false);
        await $c.win.alert('기준금리를 기타 선택시 \n\r기타 기준금리 항목만 입력하십시오.');
        $c.util.getComponent("slc_coupnRtRemainPdCd").setValue('');
        $c.util.getComponent("slc_coupnRtDecsnSpdSgn").setValue('');
        $c.util.getComponent("ipt_coupnRtDecsnSpd").setValue('');
        $c.util.getComponent("cal_coupnRtDecsnBasDd").setValue('');
        /* 수동 전환 필요: coupn_rt_decsn_tm[0] 선택 해제 — 웹스퀘어 그룹 등가 미정 */ void 0;
        /* 수동 전환 필요: coupn_rt_decsn_tm[1] 선택 해제 — 웹스퀘어 그룹 등가 미정 */ void 0;
        $c.util.getComponent('ipt_coupnRtDecsnTm').setItemDisabled(0, !!(true));
        $c.util.getComponent('ipt_coupnRtDecsnTm').setItemDisabled(1, !!(true));
        $c.util.getComponent('slc_coupnRtRemainPdCd').setDisabled(true);
        $c.util.getComponent('slc_coupnRtDecsnSpdSgn').setDisabled(true);
        $c.util.getComponent('ipt_coupnRtDecsnSpd').setDisabled(true);
        $c.util.getComponent('cal_coupnRtDecsnBasDd').setDisabled(true);
        $c.util.getComponent("ipt_coupnRtMiscBasIntContn").focus();
    } else {
        $c.util.getComponent('slc_coupnRtRemainPdCd').setDisabled(false);
        $c.util.getComponent('slc_coupnRtDecsnSpdSgn').setDisabled(false);
        $c.util.getComponent('ipt_coupnRtDecsnSpd').setDisabled(false);
        $c.util.getComponent('cal_coupnRtDecsnBasDd').setDisabled(false);
        $c.util.getComponent('ipt_coupnRtDecsnTm').setItemDisabled(0, !!(false));
        $c.util.getComponent('ipt_coupnRtDecsnTm').setItemDisabled(1, !!(false));
        $c.util.getComponent('ipt_coupnRtMiscBasIntContn').setDisabled(true);
        $c.util.getComponent("ipt_coupnRtMiscBasIntContn").setValue('');
    }
};

/**
 * @method
 * @name data_Chk
 * @description data Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.data_Chk = async function () {
    if ($c.str.getByteLength($c.util.getComponent('slc_coupnRtDecsnBasIntCd').getValue()) === 0) {
        await $c.win.alert('표면이자율결정 기준금리를 선택하십시오.');
        $c.util.getComponent("slc_coupnRtDecsnBasIntCd").focus();
        return false;
    }
    if ($c.util.getComponent('slc_coupnRtDecsnBasIntCd').getValue() !== '90') {
        if ($c.str.getByteLength($c.util.getComponent('slc_coupnRtDecsnSpdSgn').getValue()) === 0) {
            await $c.win.alert('표면이자율결정 가산금리의 기호를 선택하십시오.');
            $c.util.getComponent("slc_coupnRtDecsnSpdSgn").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_coupnRtDecsnSpd').getValue()) === 0) {
            await $c.win.alert('표면이자율결정 가산금리를 입력하십시오.');
            $c.util.getComponent("ipt_coupnRtDecsnSpd").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('cal_coupnRtDecsnBasDd').getValue()) === 0) {
            await $c.win.alert('표면이자율결정 기준일을 입력하십시오.');
            $c.util.getComponent("cal_coupnRtDecsnBasDd").focus();
            return false;
        }
        if (!($c.util.getComponent('ipt_coupnRtDecsnTm').getValue() !== '') && !($c.util.getComponent('ipt_coupnRtDecsnTm_2').getValue() !== '')) {
            await $c.win.alert('표면이자율결정을 선택하십시오.');
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_coupnRtMiscBasIntContn').getValue()) > 0) {
            await $c.win.alert('기준금리를 기타선택시만 입력항목입니다.');
            $c.util.getComponent("ipt_coupnRtMiscBasIntContn").focus();
            return false;
        }
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_coupnRtMiscBasIntContn').getValue()) === 0) {
            await $c.win.alert('기타 기준금리를 선택하십시오.');
            $c.util.getComponent("ipt_coupnRtMiscBasIntContn").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_coupnRtMiscBasIntContn').getValue()) > 20) {
            await $c.win.alert('기타 기준금리를 한글 10자, 영문 20자 이내로 입력하십시오.');
            $c.util.getComponent("ipt_coupnRtMiscBasIntContn").focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name c_std_int_form
 * @description c std int form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.c_std_int_form = async function () {
    if (!await scwin.data_Chk()) {
        return;
    }

    const parentfm = ((scwin.openerScwin())["SendForm"] !== undefined ? (scwin.openerScwin())["SendForm"] : undefined);
    $c.util.getComponent("slc_coupnRtDecsnBasIntCd").setValue($c.util.getComponent('slc_coupnRtDecsnBasIntCd').getValue());
    $c.util.getComponent("slc_coupnRtRemainPdCd").setValue($c.util.getComponent('slc_coupnRtRemainPdCd').getValue());
    $c.util.getComponent("slc_coupnRtDecsnSpdSgn").setValue($c.util.getComponent('slc_coupnRtDecsnSpdSgn').getValue());
    $c.util.getComponent("ipt_coupnRtDecsnSpd").setValue($c.util.getComponent('ipt_coupnRtDecsnSpd').getValue());
    $c.util.getComponent("cal_coupnRtDecsnBasDd").setValue($c.util.getComponent('cal_coupnRtDecsnBasDd').getValue());
    if (($c.util.getComponent('ipt_coupnRtDecsnTm').getValue() !== '')) {
        $c.util.getComponent("ipt_coupnRtDecsnTm").setValue('1');
    } else {
        if (($c.util.getComponent('ipt_coupnRtDecsnTm_2').getValue() !== '')) {
            $c.util.getComponent("ipt_coupnRtDecsnTm").setValue('2');
        }
    }
    $c.util.getComponent("ipt_coupnRtMiscBasIntContn").setValue($c.util.getComponent('ipt_coupnRtMiscBasIntContn').getValue());
    if (parentfm.int_pay_methd_cd[0].checked || parentfm.int_pay_methd_cd[1].checked || parentfm.int_pay_methd_cd[2].checked || parentfm.int_pay_methd_cd[3].checked || parentfm.int_pay_methd_cd[4].checked || parentfm.int_pay_methd_cd[5].checked) {
        parentfm.spd_sgn.value = "";
        parentfm.spd.value = "";
        parentfm.int_rt_decsn_bas_dd.value = "";
        parentfm.int_rt_decsn_tm_cd.value = "";
        parentfm.int_rt_decsn_misc_bas_int_nm.value = "";
    } else {
        $c.util.getComponent("slc_coupnRtDecsnBasIntCd").setValue($c.util.getComponent('slc_coupnRtDecsnBasIntCd').getValue());
        parentfm.spd_sgn.value = $c.util.getComponent('slc_coupnRtDecsnSpdSgn').getValue();
        parentfm.spd.value = $c.util.getComponent('ipt_coupnRtDecsnSpd').getValue();
        parentfm.int_rt_decsn_bas_dd.value = $c.util.getComponent('cal_coupnRtDecsnBasDd').getValue();
        if (($c.util.getComponent('ipt_coupnRtDecsnTm').getValue() !== '')) {
            parentfm.int_rt_decsn_tm_cd.value = '1';
        } else {
            if (($c.util.getComponent('ipt_coupnRtDecsnTm_2').getValue() !== '')) {
                parentfm.int_rt_decsn_tm_cd.value = '2';
            }
        }
        parentfm.int_rt_decsn_misc_bas_int_nm.value = $c.util.getComponent('ipt_coupnRtMiscBasIntContn').getValue();
    }
    parentfm.coupn_rt_save_yn.value = "Y";
    parent.$c.win.closePopup();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
